const t = $('Entrada').item.json;
const cp = String(t.cp || '').replace(/[^0-9]/g,'').slice(0,5);
return [{ json: { cp_clean: cp } }];

const t = $('Entrada').item.json;
const cpc = $('Limpiar cp').first().json.cp_clean;
const v = $("Call 'Validar CP'").first().json;
const cpValido = v && v.valido === true;
const municipio = cpValido ? (v.municipio || '') : '';

const raw = $('Leer estado').first().json.estado_raw;
let estado = raw ? JSON.parse(raw) : { cliente:{
  telefono:t.telefono,
  nombre:'',
  ciudad:'',
  cp:'',
  direccion:'',
  tipo_cliente:''
}, productos:[], fotos:[], updated_at:0 };

if (!estado.cliente) estado.cliente = { telefono:t.telefono, nombre:'', ciudad:'', cp:'', direccion:'', tipo_cliente:'' };
const set = (k,val) => { if (val !== undefined && val !== null && String(val).trim() !== '') estado.cliente[k] = String(val).trim(); };
set('nombre', t.nombre); set('direccion', t.direccion); set('tipo_cliente', t.tipo_cliente);
if (cpValido) { estado.cliente.cp = cpc; estado.cliente.ciudad = municipio; }

const c = estado.cliente;
const cpDadoInvalido = (String(t.cp||'').trim() !== '' && !cpValido);
const faltan = [];
if (!c.nombre)       faltan.push('nombre y apellido');
if (!c.direccion)    faltan.push('dirección de la obra (calle y número)');
if (!c.cp)           faltan.push(cpDadoInvalido ? 'un código postal válido (5 dígitos)' : 'código postal');
if (!c.tipo_cliente) faltan.push('tipo de cliente');
const completo = faltan.length === 0;
if (completo) estado.fase_datos = false;
estado.updated_at = Date.now();

const resumen =
  '• Nombre: ' + (c.nombre || '-') + '\n' +
  '• Dirección: ' + (c.direccion || '-') + '\n' +
  '• CP: ' + (c.cp || '-') + (c.ciudad ? ' (' + c.ciudad + ')' : '') + '\n' +
  '• Tipo: ' + (c.tipo_cliente || '-');

const productos = estado.productos || [];
const listaProd = productos.map(p => `${p.producto}${p.cantidad && p.cantidad !== '1' ? ' x' + p.cantidad : ''}`).join(', ');
const _pfx = String(t.telefono||'').replace(/[^0-9]/g,'').endsWith('573166083511') ? '[PRUEBA] ' : '';
const _dir = [c.direccion, [c.cp,c.ciudad].filter(Boolean).join(' ')].filter(Boolean).join(', ');
const nombre_lead = _pfx + (c.nombre || 'Cliente') + (_dir ? ' \u2014 ' + _dir : (listaProd ? ' \u2014 ' + listaProd : ''));

return [{ json: { cliente_id:t.cliente_id, telefono:t.telefono, estado:JSON.stringify(estado), completo, faltan, nombre:c.nombre||'', resumen, lead_id: estado.lead_id || null, nombre_lead, cp_cliente: estado.cliente.cp||'', direccion_cliente: estado.cliente.direccion||'', completo_geo: completo } }];

