const pf = $('Partner id final').item.json;
const g = $('Guardar datos').item.json;
let estado = {};
try { estado = JSON.parse(g.estado || '{}'); } catch(e) {}
const cli = estado.cliente || {};
const ODOO={url:'https://selfa2.odoo.com',db:'selfa2',uid:2,pwd:'17bfcdc987742e11fe6a5eaacd36d25da2174e11'};
async function odooCall(ctx,model,method,args,kwargs){
  const r=await ctx.helpers.httpRequest({method:'POST',url:ODOO.url+'/jsonrpc',headers:{'Content-Type':'application/json'},
    body:{jsonrpc:'2.0',method:'call',id:1,params:{service:'object',method:'execute_kw',args:[ODOO.db,ODOO.uid,ODOO.pwd,model,method,args,kwargs||{}]}},json:true});
  if(r.error) throw new Error(JSON.stringify(r.error));
  return r.result;
}
const tel = g.telefono || cli.telefono || '';
// tipo_cliente -> x_tipo_cliente (b2c particular / b2b constructor)
const tc = (cli.tipo_cliente||'').toLowerCase();
const x_tipo = (tc.includes('constru')||tc.includes('empresa')||tc.includes('b2b')) ? 'b2b' : 'b2c';
// campos comunes
const vals = {
  name: pf.nombre_lead,
  contact_name: pf.nombre,
  partner_name: g.nombre,
  street: g.direccion_cliente || cli.direccion || '',
  zip: g.cp_cliente || cli.cp || '',
  city: cli.ciudad || '',
  phone: tel,
  x_movil_cliente: tel,
  x_tipo_cliente: x_tipo,
  active: true
};
if (pf.partner_id) vals.partner_id = pf.partner_id;

let leadId = pf.lead_id ? parseInt(pf.lead_id) : null;
// verificar que el lead_id sea válido y activo; si no, buscar por teléfono
if (leadId) {
  const ex = await odooCall(this,'crm.lead','search',[[['id','=',leadId]]],{context:{active_test:false}});
  if (!ex || !ex.length) leadId = null;
}
if (!leadId && tel) {
  const found = await odooCall(this,'crm.lead','search',[['|',['phone','ilike',tel],['phone_sanitized','ilike',tel],['active','=',true]]],{limit:1,order:'id desc'});
  if (found && found.length) leadId = found[0];
}
let creado = false;
if (leadId) {
  await odooCall(this,'crm.lead','write',[[leadId], vals]);
} else {
  vals.type = 'opportunity';
  vals.stage_id = 29; // Solicitud de Presupuesto
  leadId = await odooCall(this,'crm.lead','create',[vals]);
  creado = true;
}
// guardar lead_id de vuelta en el estado Redis para futuros pasos
estado.lead_id = leadId;
return [{ json: { lead_id: leadId, creado, nombre_lead: pf.nombre_lead, estado: JSON.stringify(estado), telefono: tel, cliente_id: g.cliente_id } }];

const found = $input.all();
const partner = (found.length && found[0].json && found[0].json.id) ? found[0].json.id : null;
const g = $('Guardar datos').first().json;
return [{ json: { partner_id: partner, existe: partner !== null, nombre: g.nombre, telefono: g.telefono, lead_id: g.lead_id, nombre_lead: g.nombre_lead } }];

const d = $('¿Contacto existe?').first().json;
let pid = d.partner_id;
if (!pid) {
  // vino de crear
  try { pid = $('Crear contacto').first().json.id; } catch(e) { pid = null; }
}
return [{ json: { partner_id: pid, lead_id: d.lead_id, nombre: d.nombre, nombre_lead: d.nombre_lead } }];

// El resumen "Estos son tus datos / Editar-Continuar-Cancelar" solo tiene sentido en captacion.
// Si el lead ya avanzo (medicion, presupuesto...) NO se envia: evita el mensaje doble y que "Continuar" relance el onboarding.
const tel = String($('Guardar datos').first().json.telefono || '').replace(/[^0-9]/g,'');
let enCaptacion = true, etapa = null;
globalThis.__L = null; // no arrastrar el lead de otra ejecución
try {
  const r = await this.helpers.httpRequest({ method:'POST', url:'https://selfa2.odoo.com/jsonrpc', json:true,
    headers:{'Content-Type':'application/json'},
    body:{ jsonrpc:'2.0', method:'call', id:1, params:{ service:'object', method:'execute_kw',
      args:['selfa2',2,'17bfcdc987742e11fe6a5eaacd36d25da2174e11','crm.lead','search_read',
        [['|',['phone','like',tel.slice(-9)],['phone_sanitized','like',tel.slice(-9)],['active','=',true]]], { fields:['id','stage_id','street','zip','city','partner_id','contact_name','name','phone'], limit:1, order:'id desc' }] } } });
  const L = (r.result||[])[0];
  if (L && L.stage_id) { etapa = L.stage_id[0]; enCaptacion = [1,28].includes(etapa); }
  globalThis.__L = L;
} catch(e) {}
// Etapa 19 (Medición · Pdte. de Pago): con la dirección ya guardada, calcular el precio, crear/actualizar la orden de medición
// y decirle al agente que le dé el precio y le pida el pago (NO preguntar horario todavía: eso va tras validar el pago).
let respuesta_med = '';
try {
  const L = globalThis.__L;
  if (etapa === 19 && L && (L.street||'').trim() && (L.zip||'').trim()) {
    const ODOO=['selfa2',2,'17bfcdc987742e11fe6a5eaacd36d25da2174e11'];
    const odoo=async(m,me,a,kw)=>{const r=await this.helpers.httpRequest({method:'POST',url:'https://selfa2.odoo.com/jsonrpc',json:true,headers:{'Content-Type':'application/json'},body:{jsonrpc:'2.0',method:'call',id:1,params:{service:'object',method:'execute_kw',args:[...ODOO,m,me,a,kw||{}]}}});if(r.error)throw new Error(JSON.stringify(r.error));return r.result;};
    const calle=String(L.street).split('\u2014')[0].trim().replace(/,\s*$/,'');
    const g=await this.helpers.httpRequest({method:'POST',url:'https://n8n-selfa.trazabis.com/webhook/v6/geocodificar-cp',json:true,timeout:15000,headers:{'Content-Type':'application/json'},body:{cp:String(L.zip).trim(),calle}});
    if (g && g.success && g.total != null) {
      const total=Number(g.total), totalStr=total.toFixed(2).replace('.',',')+' €';
      const despl=Number(g.desplazamiento)||0, km=Math.round(Number(g.km_ida_vuelta)||0);
      const os=await odoo('sale.order','search_read',[[['opportunity_id','=',L.id],['origin','=','MEDICION_V6']]],{fields:['id','order_line'],limit:1});
      let oid=null;
      if (os.length) { oid=os[0].id; if (os[0].order_line&&os[0].order_line.length) await odoo('sale.order.line','unlink',[os[0].order_line]); }
      else { let pid=L.partner_id?L.partner_id[0]:null; if(!pid) pid=await odoo('res.partner','create',[{name:L.contact_name||L.name||'Cliente',phone:L.phone||'',street:L.street||'',zip:L.zip||'',city:L.city||''}]);
             oid=await odoo('sale.order','create',[{partner_id:pid,opportunity_id:L.id,origin:'MEDICION_V6',state:'draft'}]); }
      await odoo('sale.order.line','create',[{order_id:oid,product_id:15,name:'Visita de medicion profesional',product_uom_qty:1,price_unit:50}]);
      if (despl>0) await odoo('sale.order.line','create',[{order_id:oid,product_id:15,name:'Desplazamiento ('+km+' km ida y vuelta)',product_uom_qty:1,price_unit:despl}]);
      const dir=calle+(L.zip&&!calle.includes(L.zip)?', '+L.zip:'')+(L.city&&!calle.toLowerCase().includes(String(L.city).toLowerCase())?' '+L.city:'');
      try { await odoo('crm.lead','message_post',[[L.id]],{body:'<p>📨 Aviso de pago de medición enviado al cliente por WhatsApp (tras darnos la dirección · '+totalStr+').</p>',message_type:'comment',subtype_xmlid:'mail.mt_note',body_is_html:true}); } catch(e) {}
      respuesta_med = 'Datos guardados y precio calculado. Responde al cliente (sin escribir LISTO) con este contenido, en un tono natural: '
        + 'la visita de medición en ' + dir + ' tiene un coste de *' + totalStr + '* (incluye desplazamiento e IVA); para reservarla debe realizar el pago y enviarnos el justificante por aquí, y en cuanto lo recibamos coordinamos el día y la hora. '
        + 'NO le preguntes todavía por horario diurno o de tarde ni ofrezcas fechas.';
    } else {
      respuesta_med = 'Datos guardados, pero no se pudo calcular el precio de la medición con esa dirección. Dile que lo revisamos y le confirmamos el coste en breve, y llama a derivar_consulta (ventas) con asunto «Medición: no se pudo calcular el precio» y la dirección que dio.';
    }
  }
} catch (e) {}
return [{ json: { ...$input.first().json, en_captacion: enCaptacion, etapa_lead: etapa, respuesta_med }, pairedItem: { item: 0 } }];
